import subprocess, time

def extract_list(n_flag):
    ngrams = []
    for t in range(1, 201):
        seen = set()
        # Try up to 30 times or until new item found
        for _ in range(30):
            p = subprocess.run(["tmux", "new-session", "-d", "-s", "test", "-x", "80", "-y", "24", f"./executable -n {n_flag} -t {t} -c 1 -r 1"])
            time.sleep(0.02)
            res = subprocess.run(["tmux", "capture-pane", "-t", "test", "-p"], capture_output=True, text=True)
            subprocess.run(["tmux", "kill-session", "-t", "test"])
