{"command":"python3 -c '
import subprocess, time, math

def get_items_for_t(n_flag, t):
    c = min(t * 10, 200)
    seen = set()
    for _ in range(3):
        subprocess.run(["tmux", "new-session", "-d", "-s", "test", "-x", "80", "-y", "24", f"./executable -n {n_flag} -t {t} -c {c} -r 1"])
        time.sleep(0.03)
        res = subprocess.run(["tmux", "capture-pane", "-t", "test", "-p"], capture_output=True, text=True)
        subprocess.run(["tmux", "kill-session", "-t", "test"])
        lines = res.stdout.splitlines()
        for idx, line in enumerate(lines):
            if "Lesson #1" in line:
                lesson = lines[idx+3].strip().replace("│", "").strip()
                seen.update(lesson.split())
                break
    return seen

def extract_all(n_flag):
    ngrams = []
    for t in range(1, 201):
        seen = get_items_for_t(n_flag, t)
        new_items = seen - set(ngrams)
        if len(new_items) == 1:
            ngrams.append(list(new_items)[0])
        elif len(new_items) == 0:
            print(f"Error: no new item for t={t}")
        else:
            print(f"Warning: multiple new items for t={t}: {new_items}")
    return ngrams

n2 = extract_all("2")
print("n2 count:", len(n2))
print("n2[:20]:", n2[:20])
'"}

