fn render_frame(
    stdout: &mut io::Stdout,
    lesson_num: u32,
    success_count: u32,
    fail_count: u32,
    target_wpm: u32,
    target_acc: u32,
    history_wpms: &[u32],
    history_accs: &[u32],
    target_text: &str,
    typed_states: &[Option<bool>],
