use std::env;
use std::fs;
use std::io::{self, stdout, Write};
use std::path::Path;
use std::process::exit;
use std::time::Instant;

use clap::{Arg, ArgAction, Command};
use crossterm::{
    cursor,
    event::{self, Event, KeyCode, KeyModifiers},
    execute,
    terminal::{self, EnterAlternateScreen, LeaveAlternateScreen},
};
use rand::Rng;

mod data;
mod layout;

struct Cleanup;
impl Drop for Cleanup {
    fn drop(&mut self) {
        let _ = terminal::disable_raw_mode();
        let _ = execute!(stdout(), LeaveAlternateScreen, cursor::Show);
    }
}

fn main() {
    let matches = Command::new("executable")
        .disable_version_flag(true)
        .arg(
            Arg::new("n")
                .short('n')
                .long("n")
                .value_name("2|3|4|w|file")
                .default_value("2")
                .help("use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file."),
        )
        .arg(
            Arg::new("top")
                .short('t')
                .long("top")
                .value_name("1-200")
                .default_value("50")
                .help("use the top X ngrams ordered by usage."),
        )
        .arg(
            Arg::new("combi")
                .short('c')
                .long("combi")
                .value_name("1-200")
                .default_value("2")
                .help("how many different ngrams to use in a single lesson."),
        )
        .arg(
            Arg::new("rep")
                .short('r')
                .long("rep")
                .value_name("number")
                .default_value("3")
                .help("how often to repeat *each* different ngram in a lesson."),
        )
        .arg(
            Arg::new("wpm")
                .short('w')
                .long("wpm")
                .value_name("number")
                .default_value("40")
                .help("the wpm threshold at which the lesson is considered a success."),
        )
        .arg(
            Arg::new("acc")
                .short('a')
                .long("acc")
                .value_name("0-100")
                .default_value("94")
                .help("the accuracy in percent at which the lesson is considered a success."),
        )
        .arg(
            Arg::new("emu-in")
                .long("emu-in")
                .value_name("layout")
                .default_value("")
                .help("your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts."),
        )
        .arg(
            Arg::new("emu-out")
                .long("emu-out")
                .value_name("layout")
                .default_value("")
                .help("the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts."),
        )
        .arg(
            Arg::new("show-ortho")
                .long("show-ortho")
                .action(ArgAction::SetTrue)
                .help("show keyboard in ortholinear format"),
        )
        .arg(
            Arg::new("nokb")
                .long("nokb")
                .action(ArgAction::SetTrue)
                .help("pass this flag to disable the keyboard layout display."),
        )
        .arg(
            Arg::new("cat")
                .long("cat")
                .action(ArgAction::SetTrue)
                .help("the most important flag. don't practice alone."),
        )
        .get_matches();

    let n_str = matches.get_one::<String>("n").unwrap();
    let top_str = matches.get_one::<String>("top").unwrap();
    let combi_str = matches.get_one::<String>("combi").unwrap();
    let rep_str = matches.get_one::<String>("rep").unwrap();
    let wpm_str = matches.get_one::<String>("wpm").unwrap();
    let acc_str = matches.get_one::<String>("acc").unwrap();
    let emu_in = matches.get_one::<String>("emu-in").unwrap();
    let emu_out = matches.get_one::<String>("emu-out").unwrap();
    let show_ortho = matches.get_flag("show-ortho");
    let nokb = matches.get_flag("nokb");
    let cat = matches.get_flag("cat");

    let top: usize = match top_str.parse() {
        Ok(v) if (1..=200).contains(&v) => v,
        _ => {
            println!("Invalid argument for top. Use a number between 1 and 200.");
            exit(1);
        }
    };

    let combi: usize = match combi_str.parse() {
        Ok(v) if (1..=200).contains(&v) => v,
        _ => {
            println!("Invalid argument for combi. Use a number between 1 and 200.");
            exit(1);
        }
    };

    let rep: usize = match rep_str.parse() {
        Ok(v) if (1..=200).contains(&v) => v,
        _ => {
            println!("Invalid argument for rep. Use a number between 1 and 200.");
            exit(1);
        }
    };

    let target_wpm: u32 = match wpm_str.parse() {
        Ok(v) if (1..=200).contains(&v) => v,
        _ => {
            println!("Invalid argument for wpm. Use a number between 1 and 200.");
            exit(1);
        }
    };

    let target_acc: u32 = match acc_str.parse() {
        Ok(v) if (0..=100).contains(&v) => v,
        _ => {
            println!("Invalid argument for acc. Use a number between 0 and 100.");
            exit(1);
        }
    };

    if (emu_in.is_empty() && !emu_out.is_empty()) || (!emu_in.is_empty() && emu_out.is_empty()) {
        println!("You need to specify both emu_in and emu_out.");
        exit(1);
    }

    let word_list: Vec<String> = match n_str.as_str() {
        "2" => data::BIGRAMS.iter().map(|s| s.to_string()).collect(),
        "3" => data::TRIGRAMS.iter().map(|s| s.to_string()).collect(),
        "4" => data::TETRAGRAMS.iter().map(|s| s.to_string()).collect(),
        "w" => data::WORDS.iter().map(|s| s.to_string()).collect(),
        file_path => {
            if !Path::new(file_path).exists() {
                println!("File not found: {}", file_path);
                exit(1);
            }
            match fs::read_to_string(file_path) {
                Ok(content) => content
                    .split(',')
                    .map(|s| s.to_string())
                    .filter(|s| !s.is_empty())
                    .collect(),
                Err(_) => {
                    println!("File not found: {}", file_path);
                    exit(1);
                }
            }
        }
    };

    if word_list.is_empty() {
        println!("Word list is empty.");
        exit(1);
    }

    // Setup terminal
    terminal::enable_raw_mode().expect("raw mode");
    let mut stdout = stdout();
    execute!(stdout, EnterAlternateScreen, cursor::Hide).expect("enter alt screen");
    let _cleanup = Cleanup;

    run_app(
        &mut stdout,
        &word_list,
        top,
        combi,
        rep,
        target_wpm,
        target_acc,
        emu_in,
        emu_out,
        show_ortho,
        nokb,
        cat,
    );
}

fn generate_lesson_text(word_list: &[String], top: usize, combi: usize, rep: usize) -> String {
    let pool_size = top.min(word_list.len());
    let mut rng = rand::thread_rng();
    let mut selected = Vec::with_capacity(combi);
    for _ in 0..combi {
        let idx = rng.gen_range(0..pool_size);
        selected.push(word_list[idx].clone());
    }
    let mut words = Vec::with_capacity(combi * rep);
    for _ in 0..rep {
        words.extend(selected.clone());
    }
    format!("{} ", words.join(" "))
}

fn run_app(
    stdout: &mut io::Stdout,
    word_list: &[String],
    top: usize,
    combi: usize,
    rep: usize,
    target_wpm: u32,
    target_acc: u32,
    emu_in: &str,
    emu_out: &str,
    show_ortho: bool,
    nokb: bool,
    cat: bool,
) {
    let mut lesson_num = 1;
    let mut success_count = 0;
    let mut fail_count = 0;
    let mut history_wpms: Vec<u32> = Vec::new();
    let mut history_accs: Vec<u32> = Vec::new();

    let mut current_target = generate_lesson_text(word_list, top, combi, rep);
    let mut typed_states: Vec<Option<bool>> = Vec::new(); // Some(true) = correct, Some(false) = wrong
    let mut total_key_presses: u32 = 0;
    let mut start_time: Option<Instant> = None;

    loop {
        // Draw frame
        render_frame(
            stdout,
            lesson_num,
            success_count,
            fail_count,
            target_wpm,
            target_acc,
            &history_wpms,
            &history_accs,
            &current_target,
            &typed_states,
            emu_out,
            show_ortho,
            nokb,
            cat,
        );

        if event::poll(std::time::Duration::from_millis(50)).unwrap_or(false) {
            if let Ok(Event::Key(key_event)) = event::read() {
                if key_event.kind != event::KeyEventKind::Press {
                    continue;
                }
                match key_event.code {
                    KeyCode::Esc => break,
                    KeyCode::Char('c') if key_event.modifiers.contains(KeyModifiers::CONTROL) => {
                        break
                    }
                    KeyCode::Backspace => {
                        if !typed_states.is_empty() {
                            typed_states.pop();
                        }
                    }
                    KeyCode::Char(c) => {
                        let translated = layout::translate_char(c, emu_in, emu_out);
                        if start_time.is_none() {
                            start_time = Some(Instant::now());
                        }
                        total_key_presses += 1;
                        let pos = typed_states.len();
                        if pos < current_target.len() {
                            let expected = current_target.chars().nth(pos).unwrap_or('\0');
                            let is_correct = translated == expected;
                            typed_states.push(Some(is_correct));

                            if typed_states.len() == current_target.len() {
                                // Lesson finished
                                let elapsed = start_time
                                    .map(|t| t.elapsed().as_secs_f64())
                                    .unwrap_or(0.001);
                                let non_space_count = current_target
                                    .chars()
                                    .filter(|ch| !ch.is_whitespace())
                                    .count() as f64;
                                let words_num = non_space_count / 5.0;
                                let minutes = (elapsed / 60.0).max(0.0001);
                                let lesson_wpm = (words_num / minutes).round() as u32;

                                let correct_count =
                                    typed_states.iter().filter(|s| **s == Some(true)).count()
                                        as f64;
                                let lesson_acc = if total_key_presses > 0 {
                                    ((correct_count / total_key_presses as f64) * 100.0).round()
                                        as u32
                                } else {
                                    100
                                };

                                if lesson_wpm >= target_wpm && lesson_acc >= target_acc {
                                    success_count += 1;
                                } else {
                                    fail_count += 1;
                                }

                                history_wpms.push(lesson_wpm);
                                history_accs.push(lesson_acc);

                                // Reset for next lesson
                                lesson_num += 1;
                                current_target = generate_lesson_text(word_list, top, combi, rep);
                                typed_states.clear();
                                total_key_presses = 0;
                                start_time = None;
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
    }
}

