pub fn get_layout_rows(name: &str) -> Option<[&'static [&'static str]; 3]> {
    let layout_name = if name.is_empty() { "qwerty" } else { name };
    match layout_name {
        "qwerty" => Some([
            &["q", "w", "e", "r", "t", "y", "u", "i", "o", "p", "[", "]"],
            &["a", "s", "d", "f", "g", "h", "j", "k", "l", ";", "'"],
            &["z", "x", "c", "v", "b", "n", "m", ",", ".", "/"],
        ]),
        "qwertz" => Some([
            &["q", "w", "e", "r", "t", "z", "u", "i", "o", "p", "ü", "+"],
            &["a", "s", "d", "f", "g", "h", "j", "k", "l", "ö", "ä"],
            &["y", "x", "c", "v", "b", "n", "m", ",", ".", "-"],
        ]),
        "azerty" => Some([
            &["a", "z", "e", "r", "t", "y", "u", "i", "o", "p", "^", "$"],
            &["q", "s", "d", "f", "g", "h", "j", "k", "l", "m", "ù"],
            &["w", "x", "c", "v", "b", "n", ",", ";", ":", "!"],
