            &["a", "o", "e", "u", "i", "d", "h", "t", "n", "s", "-"],
            &[";", "q", "j", "k", "x", "b", "m", "w", "v", "z"],
        ]),
        "colemak" => Some([
            &["q", "w", "f", "p", "g", "j", "l", "u", "y", ";", "[", "]"],
            &["a", "r", "s", "t", "d", "h", "n", "e", "i", "o", "'"],
            &["z", "x", "c", "v", "b", "k", "m", ",", ".", "/"],
        ]),
        "colemakdh" => Some([
            &["q", "w", "f", "p", "b", "j", "l", "u", "y", ";", "[", "]"],
