pub fn translate_char(c: char, emu_in: &str, emu_out: &str) -> char {
    if emu_in.is_empty() || emu_out.is_empty() {
        return c;
    }
    let rows_in = match get_layout_rows(emu_in) {
        Some(r) => r,
        None => return c,
    };
    let rows_out = match get_layout_rows(emu_out) {
        Some(r) => r,
        None => return c,
    };

    let s = c.to_string();
    for r in 0..3 {
        for col in 0..rows_in[r].len() {
            if rows_in[r][col] == s {
                if col < rows_out[r].len() {
                    return rows_out[r][col].chars().next().unwrap_or(c);
                }
            }
        }
    }
    c
}

pub fn get_keyboard_lines(
    emu_out: &str,
    show_ortho: bool,
    nokb: bool,
    cat: bool,
) -> Vec<String> {
    if nokb {
        return vec![
            "│                                                                             │".to_string(),
            "│                                                                             │".to_string(),
            "│                                                                             │".to_string(),
            "│                                                                             │".to_string(),
            "│                                                                             │".to_string(),
            "│                                                                             │".to_string(),
            "│                                                                             │".to_string(),
        ];
    }

    let rows = get_layout_rows(emu_out).unwrap_or_else(|| get_layout_rows("qwerty").unwrap());

    let (pad0, pad1, pad2) = if cat { (5, 6, 7) } else { (13, 14, 15) };

    if show_ortho {
        // Ortholinear
        let mut l0 = format!("│{}\x1b[38;5;7m┌───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┬───┐", " ".repeat(pad0));
        let mut l1 = format!("│{}\x1b[38;5;7m│", " ".repeat(pad0));
        for k in rows[0] {
            l1.push_str(&format!(" {} │", k));
        }

        let mut l2 = format!("│{}\x1b[38;5;7m├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤", " ".repeat(pad0));
        let mut l3 = format!("│{}\x1b[38;5;7m│", " ".repeat(pad0));
        for k in rows[1] {
            l3.push_str(&format!(" {} │", k));
        }
        for _ in rows[1].len()..12 {
            l3.push_str(" △ │");
        }

        let mut l4 = format!("│{}\x1b[38;5;7m├───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┼───┤", " ".repeat(pad0));
        let mut l5 = format!("│{}\x1b[38;5;7m│", " ".repeat(pad0));
        for k in rows[2] {
            l5.push_str(&format!(" {} │", k));
        }
        for _ in rows[2].len()..12 {
            l5.push_str(" △ │");
        }

        let mut l6 = format!("│{}\x1b[38;5;7m└───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┴───┘", " ".repeat(pad0));

        if cat {
            l0.push_str("                       \x1b[39m│");
            l1.push_str("                       \x1b[39m│");
            l2.push_str("          /\\_/\\        \x1b[39m│");
            l3.push_str("         >(•༝• )<      \x1b[39m│");
            l4.push_str("          |    \\       \x1b[39m│");
            l5.push_str("          || |  )      \x1b[39m│");
            l6.push_str("          ll-l-//      \x1b[39m│");
        } else {
            l0.push_str("               \x1b[39m│");
            l1.push_str("               \x1b[39m│");
            l2.push_str("               \x1b[39m│");
            l3.push_str("               \x1b[39m│");
            l4.push_str("               \x1b[39m│");
            l5.push_str("               \x1b[39m│");
            l6.push_str("               \x1b[39m│");
        }

        vec![l0, l1, l2, l3, l4, l5, l6]
