fn generate_lesson_text(word_list: &[String], top: usize, combi: usize, rep: usize) -> String {
    let pool_size = top.min(word_list.len());
    let mut rng = rand::thread_rng();
    let mut selected = Vec::with_capacity(combi);
    for _ in 0..combi {
        let idx = rng.gen_range(0..pool_size);
        selected.push(word_list[idx].clone());
    }
    let mut words = Vec::with_capacity(combi * rep);
    for _ in 0..rep {
        words.extend(selected.clone());
    }
    format!("{} ", words.join(" "))
}

fn run_app(
    stdout: &mut io::Stdout,
    word_list: &[String],
    top: usize,
    combi: usize,
    rep: usize,
    target_wpm: u32,
    target_acc: u32,
    emu_in: &str,
    emu_out: &str,
    show_ortho: bool,
    nokb: bool,
    cat: bool,
) {
    let mut lesson_num = 1;
    let mut success_count = 0;
    let mut fail_count = 0;
    let mut history_wpms: Vec<u32> = Vec::new();
    let mut history_accs: Vec<u32> = Vec::new();

    let mut current_target = generate_lesson_text(word_list, top, combi, rep);
    let mut typed_states: Vec<Option<bool>> = Vec::new();
    let mut total_key_presses: u32 = 0;
    let mut start_time: Option<Instant> = None;

    loop {
        render_frame(
            stdout,
            lesson_num,
            success_count,
            fail_count,
            target_wpm,
            target_acc,
            &history_wpms,
            &history_accs,
            &current_target,
            &typed_states,
            emu_out,
            show_ortho,
            nokb,
            cat,
        );

        if event::poll(std::time::Duration::from_millis(50)).unwrap_or(false) {
            if let Ok(Event::Key(key_event)) = event::read() {
                if key_event.kind != event::KeyEventKind::Press {
                    continue;
                }
                match key_event.code {
                    KeyCode::Esc => break,
                    KeyCode::Char('c') if key_event.modifiers.contains(KeyModifiers::CONTROL) => {
                        break
                    }
                    KeyCode::Backspace => {
                        if !typed_states.is_empty() {
                            typed_states.pop();
                        }
                    }
                    KeyCode::Char(c) => {
                        let translated = layout::translate_char(c, emu_in, emu_out);
                        if start_time.is_none() {
                            start_time = Some(Instant::now());
                        }
                        total_key_presses += 1;
                        let pos = typed_states.len();
                        if pos < current_target.len() {
                            let expected = current_target.chars().nth(pos).unwrap_or('\0');
                            let is_correct = translated == expected;
                            typed_states.push(Some(is_correct));

                            if typed_states.len() == current_target.len() {
                                // Lesson finished
                                let elapsed = start_time
                                    .map(|t| t.elapsed().as_secs_f64())
                                    .unwrap_or(0.001);
                                let non_space_count = current_target
                                    .chars()
                                    .filter(|ch| !ch.is_whitespace())
                                    .count() as f64;
                                let words_num = non_space_count / 5.0;
                                let minutes = (elapsed / 60.0).max(0.0001);
                                let lesson_wpm = (words_num / minutes).round() as u32;

                                let correct_count =
                                    typed_states.iter().filter(|s| **s == Some(true)).count()
                                        as f64;
                                let lesson_acc = if total_key_presses > 0 {
                                    ((correct_count / total_key_presses as f64) * 100.0).round()
                                        as u32
                                } else {
                                    100
                                };

                                if lesson_wpm >= target_wpm && lesson_acc >= target_acc {
                                    success_count += 1;
                                } else {
                                    fail_count += 1;
                                }

                                history_wpms.push(lesson_wpm);
                                history_accs.push(lesson_acc);

                                // Reset for next lesson
                                lesson_num += 1;
                                current_target = generate_lesson_text(word_list, top, combi, rep);
                                typed_states.clear();
                                total_key_presses = 0;
                                start_time = None;
                            }
                        }
                    }
                    _ => {}
                }
            }
        }
    }
}

fn render_frame(
    stdout: &mut io::Stdout,
    lesson_num: u32,
    success_count: u32,
    fail_count: u32,
    target_wpm: u32,
    target_acc: u32,
    history_wpms: &[u32],
    history_accs: &[u32],
    target_text: &str,
    typed_states: &[Option<bool>],
    emu_out: &str,
    show_ortho: bool,
    nokb: bool,
    cat: bool,
) {
    let mut buf = String::with_capacity(4096);
    buf.push_str("\x1b[1;1H");

    let avg_wpm = if history_wpms.is_empty() {
        0
    } else {
        (history_wpms.iter().sum::<u32>() as f64 / history_wpms.len() as f64).round() as u32
    };
    let last_wpm = history_wpms.last().copied().unwrap_or(0);

    let avg_acc = if history_accs.is_empty() {
        0
    } else {
        (history_accs.iter().sum::<u32>() as f64 / history_accs.len() as f64).round() as u32
    };
    let last_acc = history_accs.last().copied().unwrap_or(0);

    // Line 0: top border
    buf.push_str("╭───────────────────────────────────────────────────────────────── Quit \x1b[1m\x1b[38;5;4m<esc> \x1b[0m\x1b[39m\x1b[49m╮\r\n");

    // Line 1: title
    buf.push_str("│                   \x1b[1m               ngrrram!\x1b[0;3m\x1b[38;5;7m\x1b[49m   by winterveil\x1b[0m\x1b[39m\x1b[49m                   │\r\n");

    // Line 2: separator
    buf.push_str("│─────────────────────────────────────────────────────────────────────────────│\r\n");

    // Line 3: lesson & stats 1
    let stats_str = format!("\x1b[38;5;2m✔: {}, \x1b[38;5;1m✘: {}\x1b[39m    ", success_count, fail_count);
    let lesson_str = format!("Lesson #{}", lesson_num);
    buf.push_str(&format!(
        "│    {:<50}{}│\r\n",
        lesson_str,
        stats_str
    ));

    // Line 4: separator
    buf.push_str("│─────────────────────────────────────────────────────────────────────────────│\r\n");

    // Line 5: empty
    buf.push_str("│                                                                             │\r\n");

    // Line 6: lesson text
    let mut text_rendered = String::new();
    let target_chars: Vec<char> = target_text.chars().collect();
    for (i, &ch) in target_chars.iter().enumerate() {
        if i < typed_states.len() {
            match typed_states[i] {
                Some(true) => {
                    text_rendered.push_str("\x1b[38;5;2m");
                    text_rendered.push(ch);
                    text_rendered.push_str("\x1b[39m");
                }
                Some(false) => {
                    text_rendered.push_str("\x1b[38;5;1m");
                    if ch == ' ' {
                        text_rendered.push('•');
                    } else {
                        text_rendered.push(ch);
                    }
                    text_rendered.push_str("\x1b[39m");
                }
                None => {
                    text_rendered.push(ch);
                }
            }
        } else {
            text_rendered.push(ch);
        }
    }

    let text_visible_len = target_chars.len();
    let left_pad = (77 - text_visible_len) / 2;
    let right_pad = 77 - text_visible_len - left_pad;

    buf.push_str("│");
    buf.push_str(&" ".repeat(left_pad));
    buf.push_str("\x1b[1m");
    buf.push_str(&text_rendered);
    buf.push_str("\x1b[0m\x1b[39m\x1b[49m");
    buf.push_str(&" ".repeat(right_pad));
    buf.push_str("│\r\n");

    // Line 7: italic grey empty line
    buf.push_str("│                             \x1b[3m\x1b[38;5;7m                  \x1b[0m\x1b[39m\x1b[49m                              │\r\n");

    // Lines 8..14: Keyboard or empty
    let kb_lines = layout::get_keyboard_lines(emu_out, show_ortho, nokb, cat);
    for kline in kb_lines {
        buf.push_str(&kline);
        buf.push_str("\r\n");
    }

    // Line 15: separator
    if cat && !nokb {
        buf.push_str("│────────────────────────────────────────────────────────────/▔▔▔▔▔▔▔▔||▔▔\\───│\r\n");
    } else {
        buf.push_str("│─────────────────────────────────────────────────────────────────────────────│\r\n");
    }

    // Line 16: WPM stats
    let cat_line16 = if cat {
        if nokb {
            "                  /\\_/\\        "
        } else {
            "                       \\\\      "
        }
    } else {
        "                               "
    };
    buf.push_str(&format!(
        "│\x1b[38;5;7m  need >= {:>3}WPM,   avg. \x1b[39m{:>3}WPM\x1b[38;5;7m,   last\x1b[39m{:>4}WPM{}\x1b[38;5;7m│\x1b[39m\r\n",
        target_wpm, avg_wpm, last_wpm, cat_line16
    ));

    // Line 17: Acc stats
    let cat_line17 = if cat {
        if nokb {
            "               >(•༝• )<      "
        } else {
            "                      V      "
        }
    } else {
        "                             "
    };
    buf.push_str(&format!(
        "│\x1b[38;5;7m  need >= {:>3}% Acc, avg. \x1b[39m{:>3}% Acc\x1b[38;5;7m, last\x1b[39m{:>4}% Acc{}\x1b[38;5;7m│\x1b[39m\r\n",
        target_acc, avg_acc, last_acc, cat_line17
    ));

    // Line 18: bottom border
    if cat && nokb {
        buf.push_str("╰────────────────────────────────────────────────────────────    |    \\───────╯");
    } else {
        buf.push_str("╰─────────────────────────────────────────────────────────────────────────────╯");
    }

    let _ = stdout.write_all(buf.as_bytes());
    let _ = stdout.flush();
}
