pub fn translate_char(c: char, emu_in: &str, emu_out: &str) -> char {
    if emu_in.is_empty() || emu_out.is_empty() {
        return c;
    }
    let rows_in = match get_layout_rows(emu_in) {
        Some(r) => r,
        None => return c,
    };
    let rows_out = match get_layout_rows(emu_out) {
        Some(r) => r,
        None => return c,
    };

    let s = c.to_string();
    for r in 0..3 {
        for col in 0..rows_in[r].len() {
            if rows_in[r][col] == s {
                if col < rows_out[r].len() {
                    return rows_out[r][col].chars().next().unwrap_or(c);
                }
            }
        }
    }
    c
}

