fn generate_lesson_text(word_list: &[String], top: usize, combi: usize, rep: usize) -> String {
    let pool_size = top.min(word_list.len());
    let mut rng = rand::thread_rng();
    let mut selected = Vec::with_capacity(combi);
    for _ in 0..combi {
        let idx = rng.gen_range(0..pool_size);
        selected.push(word_list[idx].clone());
    }
    let mut words = Vec::with_capacity(combi * rep);
    for _ in 0..rep {
        words.extend(selected.clone());
    }
    format!("{} ", words.join(" "))
}

fn run_app(
    stdout: &mut io::Stdout,
    word_list: &[String],
    top: usize,
    combi: usize,
    rep: usize,
    target_wpm: u32,
    target_acc: u32,
