                .long("emu-out")
                .value_name("layout")
                .default_value("")
                .help("the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts."),
        )
        .arg(
            Arg::new("show-ortho")
                .long("show-ortho")
                .action(ArgAction::SetTrue)
                .help("show keyboard in ortholinear format"),
        )
        .arg(
            Arg::new("nokb")
                .long("nokb")
                .action(ArgAction::SetTrue)
                .help("pass this flag to disable the keyboard layout display."),
        )
        .arg(
            Arg::new("cat")
                .long("cat")
                .action(ArgAction::SetTrue)
                .help("the most important flag. don't practice alone."),
        )
        .get_matches();

    let n_str = matches.get_one::<String>("n").unwrap();
    let top_str = matches.get_one::<String>("top").unwrap();
    let combi_str = matches.get_one::<String>("combi").unwrap();
    let rep_str = matches.get_one::<String>("rep").unwrap();
    let wpm_str = matches.get_one::<String>("wpm").unwrap();
    let acc_str = matches.get_one::<String>("acc").unwrap();
    let emu_in = matches.get_one::<String>("emu-in").unwrap();
    let emu_out = matches.get_one::<String>("emu-out").unwrap();
