        exit(1);
    }

    let word_list: Vec<String> = match n_str.as_str() {
        "2" => data::BIGRAMS.iter().map(|s| s.to_string()).collect(),
        "3" => data::TRIGRAMS.iter().map(|s| s.to_string()).collect(),
        "4" => data::TETRAGRAMS.iter().map(|s| s.to_string()).collect(),
        "w" => data::WORDS.iter().map(|s| s.to_string()).collect(),
        file_path => {
            if !Path::new(file_path).exists() {
                println!("File not found: {}", file_path);
                exit(1);
            }
            match fs::read_to_string(file_path) {
                Ok(content) => content
                    .split(',')
                    .map(|s| s.to_string())
                    .filter(|s| !s.is_empty())
                    .collect(),
                Err(_) => {
                    println!("File not found: {}", file_path);
                    exit(1);
                }
            }
        }
    };

    if word_list.is_empty() {
        println!("Word list is empty.");
        exit(1);
    }

